"""Preserve phase preimages and run the required initial root install."""
import datetime
import hashlib
import json
from pathlib import Path
import shutil
import subprocess

PHASE = Path(__file__).resolve().parent
ROOT = PHASE.parents[1]


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_json(path, value):
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + '\n')


def main():
    out = PHASE / 'initial'
    out.mkdir(exist_ok=False)
    paths = sorted(path for path in (ROOT / 'core/sail/lmdb/src').rglob('*') if path.is_file())
    write_json(out / 'module-sources.json', {str(path.relative_to(ROOT)): digest(path) for path in paths})
    for name in ('NativeResultMaterializer.java', 'NativeResultMaterializerTest.java'):
        kind = 'main' if name == 'NativeResultMaterializer.java' else 'test'
        path = ROOT / f'core/sail/lmdb/src/{kind}/java/org/eclipse/rdf4j/sail/lmdb/evaluation' / name
        shutil.copyfile(path, out / name)
    for label, argv in [('status', ['git', 'status', '--porcelain=v1', '-uall']),
                        ('head', ['git', 'rev-parse', 'HEAD']),
                        ('branch', ['git', 'branch', '--show-current'])]:
        (out / (label + '.txt')).write_bytes(subprocess.check_output(argv, cwd=ROOT))
    index = subprocess.check_output(['git', 'rev-parse', '--git-path', 'index'], cwd=ROOT, text=True).strip()
    index_path = Path(index)
    if not index_path.is_absolute():
        index_path = ROOT / index_path
    write_json(out / 'identity.json', {
        'head': (out / 'head.txt').read_text().strip(),
        'branch': (out / 'branch.txt').read_text().strip(),
        'indexSha256': digest(index_path),
        'materializerSha256': digest(out / 'NativeResultMaterializer.java'),
        'materializerTestSha256': digest(out / 'NativeResultMaterializerTest.java'),
        'moduleSourceCount': len(paths),
    })
    argv = ['../mvn', '-o', '-Dmaven.repo.local=.m2_repo', '-Dmaven.compiler.showWarnings=false',
            '-T', '1C', '-Pquick', '-DskipFrontend=true', 'clean', 'install']
    record = {'argv': argv, 'cwd': str(ROOT),
              'started': datetime.datetime.now(datetime.timezone.utc).isoformat()}
    write_json(out / 'build-command.json', record)
    print('initial root install started ' + record['started'], flush=True)
    with (out / 'maven-build.log').open('wb') as log:
        result = subprocess.run(argv, cwd=ROOT, stdout=log, stderr=subprocess.STDOUT)
    shutil.copyfile(out / 'maven-build.log', ROOT / 'maven-build.log')
    record.update(exit_code=result.returncode,
                  finished=datetime.datetime.now(datetime.timezone.utc).isoformat())
    write_json(out / 'build-command.json', record)
    print('initial root install exited ' + str(result.returncode), flush=True)
    if result.returncode:
        print('\n'.join((out / 'maven-build.log').read_text(errors='replace').splitlines()[-80:]))
    raise SystemExit(result.returncode)


if __name__ == '__main__':
    main()
